import { 
  StyleSheet, 
  View, 
  Text, 
  TouchableOpacity, 
  Pressable,
  TextInput, 
  ScrollView, 
  Alert, 
  Modal,
  KeyboardAvoidingView,
  Platform,
  SafeAreaView,
  ActivityIndicator,
  Keyboard,
  Vibration,
  Dimensions,
  Image
} from 'react-native';
import { initializeApp } from 'firebase/app';
import { 
  getDatabase, 
  ref, 
  onValue, 
  set, 
  get, 
  off,
  update
} from 'firebase/database';
import { debounce } from 'lodash';
import { ScrollView as GestureScrollView } from 'react-native-gesture-handler';
import { DiceRoller } from './components/DiceModel';
import { deleteCharacter } from './firebase';
import { AoeControls } from './components/AoeControls';
import { AOE_TYPES, AOE_SIZES } from './constants';

// Firebase configuration
const firebaseConfig = {
  apiKey: "AIzaSyBSy8ia6vKnq95_gbO7lnohVbyAQzqBtk4",
  authDomain: "dndcombattracker-572b0.firebaseapp.com",
  databaseURL: "https://dndcombattracker-572b0-default-rtdb.firebaseio.com",
  projectId: "dndcombattracker-572b0",
  storageBucket: "dndcombattracker-572b0.firebasestorage.app",
  messagingSenderId: "812186225431",
  appId: "1:812186225431:web:8da48e238d10db01d14552"
};

// Initialize Firebase
const app = initializeApp(firebaseConfig);
const database = getDatabase(app);

// Theme configuration - Move this to the top
const THEME = {
  primary: {
    main: '#1E2028',
    light: '#272935',
    dark: '#15161C',
    accent: '#2A2D3A'
  },
  secondary: {
    main: '#6D28D9', // Purple
    light: '#7C3AED',
    dark: '#5B21B6'
  },
  accent: {
    red: '#DC2626',
    green: '#059669',
    blue: '#2563EB',
    gold: '#D97706'
  },
  text: {
    primary: '#FFFFFF',
    secondary: '#94A3B8',
    accent: '#CBD5E1'
  },
  border: {
    light: 'rgba(255, 255, 255, 0.1)',
    medium: 'rgba(255, 255, 255, 0.15)',
    heavy: 'rgba(255, 255, 255, 0.2)'
  },
  shadow: {
    sm: '0 2px 4px rgba(0, 0, 0, 0.3)',
    md: '0 4px 6px rgba(0, 0, 0, 0.4)',
    lg: '0 10px 15px rgba(0, 0, 0, 0.5)'
  },
  gradient: {
    primary: ['#1E2028', '#15161C'],
    secondary: ['#6D28D9', '#5B21B6'],
    accent: ['#2A2D3A', '#1E2028']
  }
};

// Constants
const LETTERS = Array.from({ length: 26 }, (_, i) => String.fromCharCode(65 + i));
const COLORS = ['#e74c3c', '#3498db', '#2ecc71', '#f1c40f', '#9b59b6', '#1abc9c', '#e67e22', '#ffffff'];
const GRID_SIZE = 10;
const ABILITY_SCORES = ['STR', 'DEX', 'CON', 'INT', 'WIS', 'CHA'];
const SKILLS = {
  STR: ['Athletics'],
  DEX: ['Acrobatics', 'Sleight of Hand', 'Stealth'],
  CON: [],
  INT: ['Arcana', 'History', 'Investigation', 'Nature', 'Religion'],
  WIS: ['Animal Handling', 'Insight', 'Medicine', 'Perception', 'Survival'],
  CHA: ['Deception', 'Intimidation', 'Performance', 'Persuasion']
};
const CURRENCY = ['CP', 'SP', 'EP', 'GP', 'PP'];
const DICE_TYPES = [
  { sides: 4, color: '#FF6B6B' },
  { sides: 6, color: '#4ECDC4' },
  { sides: 8, color: '#45B7D1' },
  { sides: 10, color: '#96CEB4' },
  { sides: 12, color: '#FFEEAD' },
  { sides: 20, color: '#D4A5A5' },
  { sides: 100, color: '#9B59B6' }
];
const STATUS_EFFECTS = [
  { 
    id: 'blinded', 
    name: 'Blinded', 
    icon: '👁️',
    duration: 0,
    endTrigger: 'endOfTurn', // or 'startOfTurn', 'action', 'save'
    saveDC: 0,
    saveType: '' // 'STR', 'DEX', etc.
  },
  { id: 'charmed', name: 'Charmed', icon: '💕' },
  { id: 'deafened', name: 'Deafened', icon: '👂' },
  { id: 'frightened', name: 'Frightened', icon: '😨' },
  { id: 'grappled', name: 'Grappled', icon: '🤼' },
  { id: 'incapacitated', name: 'Incapacitated', icon: '💫' },
  { id: 'invisible', name: 'Invisible', icon: '👻' },
  { id: 'paralyzed', name: 'Paralyzed', icon: '⚡' },
  { id: 'petrified', name: 'Petrified', icon: '🗿' },
  { id: 'poisoned', name: 'Poisoned', icon: '🤢' },
  { id: 'prone', name: 'Prone', icon: '⬇️' },
  { id: 'restrained', name: 'Restrained', icon: '⛓️' },
  { id: 'stunned', name: 'Stunned', icon: '💫' },
  { id: 'unconscious', name: 'Unconscious', icon: '💤' }
];

// Add near other constants
const BASIC_MONSTERS = {
  goblin: {
    name: "Goblin",
    hp: 7,
    maxHp: 7,
    ac: 15,
    initiativeBonus: 2,
    cr: "1/4",
    type: "Humanoid"
  },
  orc: {
    name: "Orc",
    hp: 15,
    maxHp: 15,
    ac: 13,
    initiativeBonus: 1,
    cr: "1/2",
    type: "Humanoid"
  },
  wolf: {
    name: "Wolf",
    hp: 11,
    maxHp: 11,
    ac: 13,
    initiativeBonus: 2,
    cr: "1/4",
    type: "Beast"
  },
  // Add more basic monsters as needed
};

// Add near other constants
const COMBAT_STATUSES = {
  SURPRISED: 'SURPRISED',
  READY: 'READY',
  DELAYED: 'DELAYED'
};

// Add near other constants
const CONDITION_DURATIONS = {
  INSTANTANEOUS: 'INSTANTANEOUS',
  ONE_ROUND: '1_ROUND',
  ONE_MINUTE: '1_MINUTE',
  TEN_MINUTES: '10_MINUTES',
  ONE_HOUR: '1_HOUR',
  EIGHT_HOURS: '8_HOURS',
  UNTIL_DISPELLED: 'UNTIL_DISPELLED'
};

// Add near other constants
const SAVE_TYPES = {
  STR: 'Strength',
  DEX: 'Dexterity',
  CON: 'Constitution',
  INT: 'Intelligence',
  WIS: 'Wisdom',
  CHA: 'Charisma'
};

// Add near other constants
const DAMAGE_TYPES = [
  'acid', 'bludgeoning', 'cold', 'fire', 'force',
  'lightning', 'necrotic', 'piercing', 'poison',
  'psychic', 'radiant', 'slashing', 'thunder'
];

// Instead, add a simple constant for initial sizing
const initialWindowDimensions = Dimensions.get('window');
const initialIsSmallScreen = initialWindowDimensions.width < 768;

// Add new styles for the header
const headerStyles = StyleSheet.create({
  container: {
    backgroundColor: THEME.primary.dark,
    borderBottomWidth: 1,
    borderBottomColor: THEME.border.medium,
  },
  content: {
    maxWidth: 1200,
    marginHorizontal: 'auto',
    width: '100%',
    padding: 20,
  },
  topBar: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: 20,
  },
  titleContainer: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 12,
  },
  logo: {
    width: 40,
    height: 40,
    borderRadius: 8,
  },
  titleText: {
    color: THEME.text.primary,
    fontSize: 24,
    fontWeight: 'bold',
    fontFamily: Platform.select({ web: 'Cinzel, serif', default: 'System' }),
  },
  controls: {
    flexDirection: 'row',
    gap: 12,
    flexWrap: 'wrap',
  },
  button: {
    flexDirection: 'row',
    alignItems: 'center',
    backgroundColor: THEME.primary.accent,
    paddingHorizontal: 16,
    paddingVertical: 10,
    borderRadius: 8,
    gap: 8,
    borderWidth: 1,
    borderColor: THEME.border.light,
  },
  buttonActive: {
    backgroundColor: THEME.secondary.main,
    borderColor: THEME.secondary.light,
  },
  buttonText: {
    color: THEME.text.primary,
    fontSize: 14,
    fontWeight: '600',
  },
  buttonIcon: {
    fontSize: 16,
    color: THEME.text.primary,
  },
  roomInfo: {
    backgroundColor: THEME.primary.light,
    padding: 8,
    borderRadius: 6,
    borderWidth: 1,
    borderColor: THEME.border.light,
  },
  roomText: {
    color: THEME.text.secondary,
    fontSize: 12,
  },
  dmBadge: {
    backgroundColor: THEME.secondary.main,
    paddingHorizontal: 8,
    paddingVertical: 4,
    borderRadius: 6,
    marginLeft: 12,
  },
  dmBadgeText: {
    color: THEME.text.primary,
    fontSize: 12,
    fontWeight: 'bold',
  },
});

// Add main content styles after headerStyles
const mainStyles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: THEME.primary.main,
  },
  content: {
    flex: 1,
  },
  contentWrapper: {
    flexDirection: initialIsSmallScreen ? 'column' : 'row',
    maxWidth: 1600, // Increased to give more room
    marginHorizontal: 'auto',
    width: '100%',
    padding: 20,
    gap: 20,
  },
  toolsSection: {
    width: initialIsSmallScreen ? '100%' : 250, // Fixed width instead of flex
    minWidth: 250,
  },
  gridSection: {
    flex: 2, // Grid takes up more space
    backgroundColor: THEME.primary.light,
    borderRadius: 12,
    borderWidth: 1,
    borderColor: THEME.border.medium,
    overflow: 'hidden',
  },
  gridHeader: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    padding: 16,
    borderBottomWidth: 1,
    borderBottomColor: THEME.border.medium,
    backgroundColor: THEME.primary.accent,
  },
  sectionTitle: {
    color: THEME.text.primary,
    fontSize: 18,
    fontWeight: '600',
  },
  gridControls: {
    flexDirection: 'row',
    gap: 8,
  },
  controlButton: {
    padding: 8,
    borderRadius: 6,
    backgroundColor: THEME.primary.main,
    borderWidth: 1,
    borderColor: THEME.border.light,
  },
  controlIcon: {
    color: THEME.text.primary,
    fontSize: 16,
  },
});

// Add grid styles after mainStyles
const gridStyles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: THEME.primary.light,
    borderRadius: 12,
    overflow: 'hidden',
  },
  header: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    padding: 16,
    backgroundColor: THEME.primary.accent,
    borderBottomWidth: 1,
    borderBottomColor: THEME.border.medium,
  },
  controls: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 12,
  },
  colorPicker: {
    flexDirection: 'row',
    gap: 8,
    padding: 12,
    backgroundColor: THEME.primary.dark,
    borderRadius: 8,
  },
  colorButton: {
    width: 24,
    height: 24,
    borderRadius: 12,
    borderWidth: 2,
    borderColor: THEME.border.light,
  },
  colorButtonSelected: {
    borderColor: THEME.secondary.main,
    borderWidth: 3,
  },
  gridContent: {
    padding: 20,
  },
  row: {
    flexDirection: 'row',
    justifyContent: 'center',
  },
  cell: {
    width: 50,
    height: 50,
    borderWidth: 1,
    borderColor: THEME.border.light,
    justifyContent: 'center',
    alignItems: 'center',
    backgroundColor: THEME.primary.dark,
  },
  cellActive: {
    borderColor: THEME.secondary.main,
    borderWidth: 2,
  },
  tokenContent: {
    width: '100%',
    height: '100%',
    justifyContent: 'center',
    alignItems: 'center',
    padding: 4,
    backgroundColor: 'rgba(0, 0, 0, 0.5)',
  },
  tokenName: {
    fontSize: 11,  // Slightly smaller font
    fontWeight: '700',
    textAlign: 'center',
    marginBottom: 1,  // Reduced margin
    textShadowColor: 'rgba(0, 0, 0, 0.75)',
    textShadowOffset: { width: 1, height: 1 },
    textShadowRadius: 2,
  },
  tokenStats: {
    fontSize: 10,
