const handleHPChange = (amount, isTemp = false) => {
  setSelectedToken(prev => {
    const newHP = Math.max(0, Math.min((prev.hp || 0) + amount, prev.maxHp));
    const newTempHP = isTemp ? Math.max(0, (prev.tempHP || 0) + amount) : (prev.tempHP || 0);
    return {
      ...prev,
      hp: newHP,
      tempHP: newTempHP
    };
  });
};

