    }
  }));
};

const addCondition = (tokenId, conditionId, duration) => {
  const newCondition = {
    id: conditionId,
    duration,
    startTime: Date.now(),
    endTrigger: STATUS_EFFECTS.find(e => e.id === conditionId)?.endTrigger
  };

  setTokens(prev => ({
    ...prev,
    [tokenId]: {
      ...prev[tokenId],
      conditions: [...(prev[tokenId].conditions || []), newCondition]
    }
  }));
};

const handleTargetSelection = useCallback((position) => {
  if (!targetMode) return;
  setSelectedTargets(prev => {
    const isAlreadySelected = prev.includes(position);
    return isAlreadySelected 
      ? prev.filter(p => p !== position)
      : [...prev, position];
  });
}, [targetMode]);

const isInAoe = useCallback((position, origin, type, size) => {
  if (!origin) return false;
  const [originRow, originCol] = origin.split('-').map(Number);
  const [targetRow, targetCol] = position.split('-').map(Number);

  switch (type) {
    case AOE_TYPES.CIRCLE:
    case AOE_TYPES.SPHERE: {
      const distance = calculateDistance(origin, position);
      return distance <= size;
    }
    case AOE_TYPES.CONE: {
      const distance = calculateDistance(origin, position);
      if (distance > size) return false;
      const angle = Math.atan2(targetRow - originRow, targetCol - originCol) * 180 / Math.PI;
      return Math.abs(angle) <= 53.13;
    }
    case AOE_TYPES.LINE: {
      const dx = Math.abs(targetCol - originCol);
      const dy = Math.abs(targetRow - originRow);
      const maxDist = size / 5;
      return (dx === 0 || dy === 0 || dx === dy) && Math.max(dx, dy) <= maxDist;
    }
    case AOE_TYPES.CUBE: {
      const dx = Math.abs(targetCol - originCol);
      const dy = Math.abs(targetRow - originRow);
      const maxDist = size / 5;
      return dx <= maxDist && dy <= maxDist;
    }
    default:
      return false;
  }
}, []);

const handleCellPress = useCallback((position) => {
  console.log('Cell pressed:', position);

  if (targetMode) {
    handleTargetSelection(position);
    return;
  }

  if (aoeMode && !selectedAoe.origin) {
    setSelectedAoe(prev => ({ ...prev, origin: position }));
    return;
  }

  // Check if there's already a token at this position
  const existingToken = Object.values(tokens).find(t => t.position === position);

  if (existingToken) {
    // Remove the token if it exists
    const newTokens = { ...tokens };
    delete newTokens[existingToken.id];
    setTokens(newTokens);

    // Update Firebase
    if (firebaseRef.current) {
      update(firebaseRef.current, {
        tokens: newTokens
      });
    }
  } else {
    // Place a new token
    const newToken = {
      id: `token-${nextTokenId}`,
      name: `Token ${nextTokenId}`,
      position,
      color: COLORS[nextTokenId % COLORS.length],
      hp: 20,
      maxHp: 20,
      conditions: []
    };

    const newTokens = {
      ...tokens,
      [newToken.id]: newToken
    };

    setTokens(newTokens);
    setNextTokenId(prev => prev + 1);

    // Update Firebase
    if (firebaseRef.current) {
      update(firebaseRef.current, {
        tokens: newTokens
      });
    }
  }
}, [targetMode, aoeMode, selectedAoe.origin, nextTokenId, tokens]);

  // Add character creation handler
  const handleAddCharacter = (newCharacter) => {
    const characterWithId = {
      ...newCharacter,
      id: `char-${Date.now()}`,
      owner: name,
    };

    setCharacters(prev => [...prev, characterWithId]);

    // Update Firebase
    if (firebaseRef.current) {
      const updates = {
        characters: [...characters, characterWithId]
      };
      update(firebaseRef.current, updates);
    }
  };

  return (
    <SafeAreaView style={styles.container}>
      {/* Player Name Modal */}
      <PlayerNameModal
        visible={showPlayerNameModal}
        onSubmit={handlePlayerNameSubmit}
      />

      {/* Room Modal - Only show if player name modal is closed */}
      {!showPlayerNameModal && (
        <RoomModal
          visible={showRoomModal}
          setShowRoomModal={setShowRoomModal}
          isConnected={isConnected}
          roomCode={roomCode}
          setRoomCode={setRoomCode}
          isJoining={isJoining}
          connectToRoom={connectToRoom}
          THEME={THEME}
        />
      )}

      {/* Main Content - Only show when connected */}
      {isConnected && (
        <View style={modernStyles.container}>
          {/* Header */}
          <View style={modernStyles.header}>
            <View style={modernStyles.headerContent}>
              <Text style={modernStyles.title}>D&D Combat Tracker</Text>
              <View style={modernStyles.headerControls}>
                <TouchableOpacity 
                  style={modernStyles.button}
                  onPress={() => setShowCustomMonsterModal(true)}
                >
                  <Text style={modernStyles.buttonText}>Add Monster</Text>
                </TouchableOpacity>
                <TouchableOpacity 
                  style={modernStyles.button}
                  onPress={() => setAoeMode(!aoeMode)}
                >
                  <Text style={modernStyles.buttonText}>
                    {aoeMode ? 'Cancel AoE' : 'Add AoE'}
                  </Text>
                </TouchableOpacity>
              </View>
            </View>
          </View>

          {/* Main Content */}
          <View style={modernStyles.mainContent}>
            {/* Sidebar */}
            <View style={modernStyles.sidebar}>
              {/* Characters Card */}
              <View style={modernStyles.card}>
                <View style={modernStyles.cardHeader}>
                  <Text style={modernStyles.cardTitle}>Characters</Text>
                  <TouchableOpacity 
                    style={modernStyles.button}
                    onPress={() => setShowCharacterModal(true)}
                  >
                    <Text style={modernStyles.buttonText}>Add Character</Text>
                  </TouchableOpacity>
                </View>
                <ScrollView style={{ maxHeight: 300 }}>
                  {characters.map(character => (
                    <TouchableOpacity
                      key={character.id}
                      style={modernStyles.characterCard}
                      onPress={() => {
                        console.log('Character clicked:', character.name);
                        setSelectedCharacter(character);
                        setShowCharacterStatsModal(true);
                      }}
                    >
                      <View style={modernStyles.characterHeader}>
                        <View style={modernStyles.characterInfo}>
                          <Text style={modernStyles.characterName}>{character.name}</Text>
                          <Text style={modernStyles.characterMeta}>
                            {character.class} - Level {character.level}
                          </Text>
                        </View>
                      </View>
                      <View style={modernStyles.statsGrid}>
                        <View style={modernStyles.statItem}>
                          <Text style={modernStyles.statLabel}>HP</Text>
                          <Text style={modernStyles.statValue}>
                            {character.hp}/{character.maxHp}
                          </Text>
                        </View>
                        <View style={modernStyles.statItem}>
                          <Text style={modernStyles.statLabel}>AC</Text>
                          <Text style={modernStyles.statValue}>{character.ac}</Text>
                        </View>
                        <View style={modernStyles.statItem}>
                          <Text style={modernStyles.statLabel}>Initiative</Text>
                          <Text style={modernStyles.statValue}>+{character.initiativeBonus}</Text>
                        </View>
                      </View>
                    </TouchableOpacity>
                  ))}
                </ScrollView>
              </View>

              {/* Character Stats Modal */}
              {selectedCharacter && (
                <CharacterSheetModal
                  visible={showCharacterStatsModal}
                  onClose={() => {
                    setShowCharacterStatsModal(false);
                    setSelectedCharacter(null);
                  }}
                  onUpdate={(updatedCharacter) => {
                    const updatedCharacters = characters.map(c => 
                      c.id === updatedCharacter.id ? updatedCharacter : c
                    );
                    setCharacters(updatedCharacters);

                    // Update Firebase
                    if (firebaseRef.current) {
                      update(firebaseRef.current, {
                        characters: updatedCharacters
                      });
                    }

                    setShowCharacterStatsModal(false);
                    setSelectedCharacter(null);
                  }}
                  character={selectedCharacter}
                  THEME={THEME}
                />
              )}

              {/* Create Character Modal */}
              <CharacterSheetModal
                visible={showCharacterModal}
                onClose={() => setShowCharacterModal(false)}
                onUpdate={(character) => {
                  handleAddCharacter(character);
                  setShowCharacterModal(false);
                }}
                character={{
                  name: '',
                  class: '',
                  level: 1,
                  hp: 10,
                  maxHp: 10,
                  ac: 10,
                  initiativeBonus: 0,
                  abilityScores: {
                    STR: 10,
                    DEX: 10,
                    CON: 10,
                    INT: 10,
                    WIS: 10,
                    CHA: 10
                  },
                  proficientSkills: [],
                }}
                THEME={THEME}
              />

              {/* Dice Panel */}
              <View style={modernStyles.dicePanel}>
                <Text style={modernStyles.cardTitle}>Dice Roller</Text>
                {/* Add dice controls here */}
              </View>
            </View>

            {/* Grid Container */}
            <View style={[modernStyles.gridContainer, { flex: 1 }]}>
              <View style={modernStyles.cardHeader}>
                <Text style={modernStyles.cardTitle}>Combat Grid</Text>
                <View style={styles.gridControls}>
                  <TouchableOpacity
                    style={[styles.controlButton, targetMode && styles.activeControl]}
                    onPress={() => setTargetMode(!targetMode)}
                  >
                    <Text style={styles.buttonText}>🎯 Target</Text>
                  </TouchableOpacity>
                  <TouchableOpacity
                    style={[styles.controlButton, aoeMode && styles.activeControl]}
                    onPress={() => {
                      setAoeMode(!aoeMode);
                      if (!aoeMode) {
                        setSelectedAoe({
                          type: AOE_TYPES.CIRCLE,
                          size: AOE_SIZES.CIRCLE[0],
                          origin: null
                        });
                      }
                    }}
                  >
                    <Text style={styles.buttonText}>💥 AoE</Text>
                  </TouchableOpacity>
                </View>
              </View>

              <View style={{ flex: 1, padding: 20 }}>
                <Grid 
                  tokens={tokens}
                  onCellPress={(position) => {
                    console.log('Grid cell pressed:', position); // Debug log
                    handleCellPress(position);
                  }}
                />
              </View>
            </View>
          </View>
        </View>
      )}
    </SafeAreaView>
  );
}
